
INSERT INTO public.email_templates (name, type, subject_template, content_template, is_active, is_default, from_email, created_by)
SELECT
  'Host Pre-Tour Briefing',
  'host_pre_tour_briefing',
  'Your upcoming tour: {{tour_name}} — Host briefing',
  $TEMPLATE$<div style="font-family: Arial, sans-serif; color: #1a1a1a; line-height: 1.5; max-width: 800px; margin: 0 auto;"><h2 style="color: #1a1a1a;">Hello {{host_first_name}},</h2><p>Your upcoming tour <strong>{{tour_name}}</strong> starts in 7 days. Below is your briefing summary.</p><h3 style="border-bottom: 2px solid #1a1a1a; padding-bottom: 4px;">Tour Overview</h3><table cellpadding="6" style="border-collapse: collapse; width: 100%;"><tr><td style="color:#555;width:35%;"><strong>Tour Name</strong></td><td>{{tour_name}}</td></tr><tr><td style="color:#555;"><strong>Start Date</strong></td><td>{{tour_start_date}}</td></tr><tr><td style="color:#555;"><strong>End Date</strong></td><td>{{tour_end_date}}</td></tr><tr><td style="color:#555;"><strong>Location</strong></td><td>{{tour_location}}</td></tr><tr><td style="color:#555;"><strong>Meeting / Pickup Point</strong></td><td>{{meeting_location}}</td></tr><tr><td style="color:#555;"><strong>Bookings</strong></td><td>{{booking_count}} bookings, {{passenger_count}} passengers</td></tr></table><h3 style="border-bottom: 2px solid #1a1a1a; padding-bottom: 4px; margin-top: 24px;">First Hotel (Check-in)</h3><table cellpadding="6" style="border-collapse: collapse; width: 100%;"><tr><td style="color:#555;width:35%;"><strong>Hotel</strong></td><td>{{first_hotel_name}}</td></tr><tr><td style="color:#555;"><strong>Address</strong></td><td>{{first_hotel_address}}</td></tr><tr><td style="color:#555;"><strong>Phone</strong></td><td>{{first_hotel_phone}}</td></tr><tr><td style="color:#555;"><strong>Check-in Date</strong></td><td>{{first_hotel_checkin}}</td></tr></table><h3 style="border-bottom: 2px solid #1a1a1a; padding-bottom: 4px; margin-top: 24px;">Admin Login</h3><p>You can log in to the admin website to access your tour information at any time.</p><table cellpadding="6" style="border-collapse: collapse;"><tr><td style="color:#555;"><strong>Website</strong></td><td><a href="{{admin_website_url}}">{{admin_website_url}}</a></td></tr><tr><td style="color:#555;"><strong>Username</strong></td><td>{{host_username}}</td></tr></table><p style="margin-top: 8px;">If you do not remember your password, use the <a href="{{forgot_password_url}}">Forgot Password</a> link on the login page.</p><h3 style="border-bottom: 2px solid #1a1a1a; padding-bottom: 4px; margin-top: 24px;">Full Host Information Report</h3><p>Click below to view the complete combined report (passenger summary, contacts, dietary, hotels, activities, pickup, itinerary). You can view it in your browser and print it from there.</p><p style="text-align:center;margin: 20px 0;"><a href="{{combined_report_link}}" style="background:#1a1a1a;color:#fff;padding:12px 24px;text-decoration:none;border-radius:4px;display:inline-block;font-weight:600;">View Combined Host Report</a></p><p style="font-size:12px;color:#777;">This link is valid for 7 days. After that, please log in to the admin site to access the report.</p><p style="margin-top: 24px;">Have a great tour!</p><p>The Australian Racing Tours Team</p></div>$TEMPLATE$,
  true,
  true,
  'bookings@australianracingtours.com.au',
  (SELECT user_id FROM public.user_roles WHERE role = 'admin' LIMIT 1)
WHERE NOT EXISTS (
  SELECT 1 FROM public.email_templates WHERE type = 'host_pre_tour_briefing' AND is_default = true
);
